/**
 * Keeps the theme metadata in sync with the theme files.
 *
 * `themes.json` is the hand-maintained source for `name`, `description` and
 * `category`. Everything else is generated from the CSS files:
 *
 *  - `themes.json`  -> the `colors` swatches (resolved from the theme tokens)
 *  - `types.ts`     -> the `ThemeName` union
 *  - `README.md`    -> the catalog between the `themes:start` / `themes:end` markers
 *
 * Usage (Bun or Node with a TypeScript runner such as tsx):
 *
 *   bun run themes/scripts/sync-metadata.ts           # write the generated files
 *   bun run themes/scripts/sync-metadata.ts --check   # exit 1 when something is stale
 *
 * Options:
 *   --themes <dir>   directory holding the theme files (default: parent of this script)
 *   --check          do not write; report stale files and exit 1
 *
 * Swatch order, identical for both color schemes:
 *   primary, fg-primary, secondary, bg, bg-subtle, bg-surface, text, text-muted, border
 */

import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { AAA_THEMES, extractVars, resolveColor, type Mode, type RGB } from './lib/css';

// ---------------------------------------------------------------------------
// Contract
// ---------------------------------------------------------------------------

const SWATCH_TOKENS = [
  '--en-primary',
  '--en-fg-primary',
  '--en-secondary',
  '--en-bg',
  '--en-bg-subtle',
  '--en-bg-surface',
  '--en-text',
  '--en-text-muted',
  '--en-border',
] as const;

/** Allowed categories, in catalog order, with their README headings. */
const CATEGORIES: Record<string, string> = {
  classic: 'Classic and special purpose',
  blue: 'Blue tones',
  brown: 'Brown / earth tones',
  red: 'Red and pink tones',
  purple: 'Purple tones',
  green: 'Green tones',
  orange: 'Orange tones',
  yellow: 'Yellow tones',
};

const README_START = '<!-- themes:start -->';
const README_END = '<!-- themes:end -->';

interface ThemeEntry {
  file: string;
  name: string;
  description: string;
  category: string;
  colors: { light: string[]; dark: string[] };
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const hex = ([r, g, b]: RGB): string => '#' + [r, g, b].map((c) => c.toString(16).padStart(2, '0')).join('').toUpperCase();

function swatches(css: string, file: string): ThemeEntry['colors'] {
  const vars = extractVars(css);
  const out = { light: [] as string[], dark: [] as string[] };
  for (const mode of ['light', 'dark'] as Mode[]) {
    const page = vars.has('--en-bg') ? resolveColor(vars.get('--en-bg')!, vars, mode) : null;
    for (const token of SWATCH_TOKENS) {
      const raw = vars.get(token);
      const rgb = raw ? resolveColor(raw, vars, mode, token === '--en-bg' ? null : page) : null;
      if (!rgb) throw new Error(`${file}: cannot resolve ${token} (${mode}) to a plain color`);
      out[mode].push(hex(rgb));
    }
  }
  return out;
}

function typesSource(entries: ThemeEntry[]): string {
  const lines: string[] = [];
  for (const category of Object.keys(CATEGORIES)) {
    const names = entries.filter((e) => e.category === category).map((e) => `'${e.file.replace(/\.css$/, '')}'`);
    if (names.length) lines.push(`  | ${names.join(' | ')}  // ${category}`);
  }
  return `/** Generated by scripts/sync-metadata.ts. Do not edit by hand. */\nexport type ThemeName =\n${lines.join('\n')}\n;\n`;
}

function catalog(entries: ThemeEntry[], css: Map<string, string>): string {
  const parts: string[] = [];
  for (const [category, heading] of Object.entries(CATEGORIES)) {
    const list = entries.filter((e) => e.category === category);
    if (!list.length) continue;
    parts.push(`### ${heading}\n`, '| Theme | File | Notes | Description |', '|-------|------|-------|-------------|');
    for (const e of list) {
      const name = e.file.replace(/\.css$/, '');
      const source = css.get(name) ?? '';
      const notes = [
        /--en-density\s*:/.test(source) ? 'layout' : '',
        /--en-bg-texture\s*:/.test(source) ? 'texture' : '',
        AAA_THEMES.has(name) ? 'AAA' : '',
      ].filter(Boolean);
      parts.push(`| ${e.name} | \`${e.file}\` | ${notes.join(', ')} | ${e.description} |`);
    }
    parts.push('');
  }
  return parts.join('\n').trimEnd();
}

function replaceBetween(text: string, start: string, end: string, body: string): string {
  const a = text.indexOf(start);
  const b = text.indexOf(end);
  if (a < 0 || b < a) throw new Error(`README.md: markers ${start} / ${end} not found`);
  return `${text.slice(0, a + start.length)}\n\n${body}\n\n${text.slice(b)}`;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

function main(): void {
  const args = process.argv.slice(2);
  const here = dirname(fileURLToPath(import.meta.url));
  const flag = args.indexOf('--themes');
  const dir = resolve(flag >= 0 ? args[flag + 1] : join(here, '..'));
  const check = args.includes('--check');

  const files = readdirSync(dir).filter((f) => f.endsWith('.css') && statSync(join(dir, f)).isFile()).sort();
  const css = new Map(files.map((f) => [f.replace(/\.css$/, ''), readFileSync(join(dir, f), 'utf8')] as const));
  const entries = JSON.parse(readFileSync(join(dir, 'themes.json'), 'utf8')) as ThemeEntry[];

  // Validation
  const problems: string[] = [];
  const listed = new Set(entries.map((e) => e.file));
  for (const f of files) if (!listed.has(f)) problems.push(`${f}: missing from themes.json (add name, description, category)`);
  for (const e of entries) {
    if (!files.includes(e.file)) problems.push(`${e.file}: listed in themes.json but the file does not exist`);
    if (!(e.category in CATEGORIES)) problems.push(`${e.file}: unknown category "${e.category}" (allowed: ${Object.keys(CATEGORIES).join(', ')})`);
    if (!e.name || !e.description) problems.push(`${e.file}: name and description are required`);
  }
  if (problems.length) {
    console.error(problems.join('\n'));
    process.exit(1);
  }

  const next = entries.map((e) => ({
    file: e.file,
    name: e.name,
    description: e.description,
    category: e.category,
    colors: swatches(css.get(e.file.replace(/\.css$/, ''))!, e.file),
  }));

  const readmePath = join(dir, 'README.md');
  const readme = existsSync(readmePath) ? readFileSync(readmePath, 'utf8') : '';
  const outputs: [string, string, string][] = [
    ['themes.json', readFileSync(join(dir, 'themes.json'), 'utf8'), `${JSON.stringify(next, null, 2)}\n`],
    ['types.ts', existsSync(join(dir, 'types.ts')) ? readFileSync(join(dir, 'types.ts'), 'utf8') : '', typesSource(next)],
    ['README.md', readme, replaceBetween(readme, README_START, README_END, catalog(next, css))],
  ];

  const stale = outputs.filter(([, current, wanted]) => current !== wanted);
  if (check) {
    if (stale.length) {
      console.error(`Out of date: ${stale.map(([n]) => n).join(', ')}. Run sync-metadata.ts without --check.`);
      process.exit(1);
    }
    console.log('Metadata is in sync.');
    return;
  }
  for (const [name, , wanted] of stale) writeFileSync(join(dir, name), wanted);
  console.log(stale.length ? `Updated: ${stale.map(([n]) => n).join(', ')}` : 'Already in sync.');
}

main();
